// Generated by esquadro: do not edit. The connection and the session
// across tabs: a bar while the browser is offline (and a notice when it is
// back; the data reload then), and signing in or out in a tab does it in
// the others.
import { useQueryClient } from "@tanstack/react-query"
import { useNavigate } from "@tanstack/react-router"
import { WifiOff } from "lucide-react"
import { useEffect, useState } from "react"
import { base } from "../config.ts"
import { sessionQuery } from "./auth.tsx"
import { t } from "./i18n.ts"
import { toast } from "./toast.tsx"

const channelName = `esquadro:${base}:session`
// This tab: the channel answers its own messages too, which it skips.
const tab = typeof crypto !== "undefined" && "randomUUID" in crypto ? crypto.randomUUID() : String(Math.random())

/** Tells the other tabs the session changed. */
export function announceSession(event: "signed-in" | "signed-out") {
  try {
    const channel = new BroadcastChannel(channelName)
    channel.postMessage({ event, tab })
    channel.close()
  } catch {
    // Without BroadcastChannel: each tab finds out on its next request.
  }
}

/** Whether the browser is online. */
export function useOnline(): boolean {
  const [online, setOnline] = useState(() => (typeof navigator === "undefined" ? true : navigator.onLine))
  useEffect(() => {
    const on = () => setOnline(true)
    const off = () => setOnline(false)
    window.addEventListener("online", on)
    window.addEventListener("offline", off)
    return () => {
      window.removeEventListener("online", on)
      window.removeEventListener("offline", off)
    }
  }, [])
  return online
}

/** The bar shown while offline. Once, in src/pages/__root.tsx. */
export function OfflineBanner() {
  const online = useOnline()
  const [wasOffline, setWasOffline] = useState(false)
  useEffect(() => {
    if (!online) setWasOffline(true)
    else if (wasOffline) {
      toast(t("backOnline"))
      setWasOffline(false)
    }
  }, [online])
  if (online) return null
  return (
    <div
      role="alert"
      className="fixed inset-x-0 top-0 z-50 flex items-center justify-center gap-2 bg-amber-500 px-4 py-1.5 text-sm font-medium text-amber-950 animate-in slide-in-from-top"
    >
      <WifiOff className="size-4" />
      {t("offlineBanner")}
    </div>
  )
}

/** Follows the session of the other tabs. Once, in src/pages/__root.tsx. */
export function SessionSync() {
  const queryClient = useQueryClient()
  const navigate = useNavigate()
  useEffect(() => {
    let channel: BroadcastChannel
    try {
      channel = new BroadcastChannel(channelName)
    } catch {
      return
    }
    channel.onmessage = (e: MessageEvent<{ event: string; tab: string }>) => {
      if (e.data?.tab === tab) return
      if (e.data?.event === "signed-out") {
        queryClient.setQueryData(sessionQuery.queryKey, null)
        queryClient.clear()
        navigate({ to: "/login", search: { redirect: undefined } })
      } else if (e.data?.event === "signed-in") {
        queryClient.invalidateQueries({ queryKey: sessionQuery.queryKey })
      }
    }
    return () => channel.close()
  }, [queryClient, navigate])
  return null
}
